preConditionHook:
// Session VWAP as the book writes it: PriceW/ShareW are EL VARIABLES reset on
// `date > date[1]` (date = wall-clock close date, EL_Date_Probe.txt) and
// otherwise carried; both start at 0 on the first calculated bar, mid-session
// or not, exactly as the EL variables do. Volume is Ticks (up + down).
// AvgPrice MEASURED with EL_AvgPrice_Probe.txt on @OJ 240min, 8,327 bars:
// (Open + High + Low + Close) / 4 summed left to right on 8,326 -- the other
// operand order differs in the last bit on 2,750 of them -- and on the ONE bar
// whose Open was 0 (2012-05-23 14:00 in TS's data) TradeStation returned
// (High + Low + Close) / 3 exactly: a zero open is treated as missing.
if (day_of(ctx.Time(0)) > day_of(ctx.Time(1))) {
    priceW = 0.0;
    shareW = 0.0;
}
double avgPrice = open[0] == 0.0 ? (high[0] + low[0] + close[0]) / 3
                                  : (open[0] + high[0] + low[0] + close[0]) / 4;
priceW = priceW + (avgPrice * (double)ctx.Ticks[0]);
shareW = shareW + (double)ctx.Ticks[0];
if (el_gt(shareW, 0.0)) vwap = priceW / shareW;
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, then updated as
// TWO statements -- EL evaluates S[1] + in - out left to right, and folding
// it to S += in - out rounds differently (@OJ 2015-02-20).
if (atrLength != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLookback;
